const makeScenario = (total, row) => {
  const [id, severity, title, situation, resource, doubt, shared, conflict] = row;
  const framing = {
    1: "En face de toi, l'autre joueur voudrait lui aussi faire avancer une histoire importante pour quelqu'un qu'il aime. Tu ne sais pas s'il espère un vrai partage ou s'il attend de voir ce que tu feras.",
    2: "L'autre joueur protège un proche lui aussi. Vous avez échangé quelques mots, mais tu ne connais ni toute sa situation ni la décision qu'il garde pour lui.",
    3: "En face, l'autre a déjà parlé de ce qui compte pour lui. Tu te demandes si cette confiance était sincère ou si elle devait seulement te faire baisser la garde.",
    4: "Vous avez peu de temps pour vous expliquer. Le geste de l'autre peut arriver avant que tu comprennes ce qu'il pense; ses paroles ne t'assurent pas qu'il partagera.",
    5: "Le silence de l'autre ne t'apprend rien. Il peut partager l'unique ressource ou la prendre pour son proche; aucune explication ne te dira si tu as attendu trop longtemps."
  }[severity];
  const pressure = {
    1: " Tu peux attendre un instant, mais pas assez longtemps pour vérifier ce que l'autre fera.",
    2: " Peut-être tiendra-t-il parole, peut-être pas. À force d'attendre, la solution se rétrécit.",
    3: " Il peut agir avant toi. Pendant que tu hésites, le temps passe et tu ne sais pas ce qui arrive à ton proche.",
    4: " Une seconde de plus peut lui laisser l'initiative; agir la première peut lui retirer sa seule chance.",
    5: " Pendant que tu hésites, la situation de ton proche peut changer sans que tu le saches. Tu devras décider sans pouvoir vérifier la promesse de l'autre."
  }[severity];
  return {
    id,
    rollTotals: [total],
    severity,
    title,
    problem: situation + "\n\n" + framing,
    resource: "Dans la mallette, " + resource + " Une personne peut en profiter pleinement; en partageant, chacun n'en reçoit qu'une partie.",
    doubt: "Tu te demandes si l'autre tiendra parole. " + doubt + pressure,
    outcomes: {
      bothShare: shared + " Vous obtenez chacun une aide partielle, sans garantie de résoudre entièrement votre problème.",
      youSteal: "Tu prends l'accès complet. Ton proche reçoit l'aide la plus complète possible; l'autre joueur perd cet accès.",
      otherSteals: "L'autre prend l'accès complet. Son proche reçoit l'aide la plus complète possible; le tien perd cet accès.",
      bothSteal: conflict + " L'accès est perdu; aucun proche ne reçoit l'aide prévue."
    }
  };
};

const pack = (total, rows) => rows.map((row) => makeScenario(total, row));

